class Solution { public int minChanges(int[] nums,int k){int inf=1_000_000;int[] dp=new int[1024];Arrays.fill(dp,inf);dp[0]=0;for(int group=0;group<k;group++){int[] count=new int[1024];int size=0;for(int i=group;i<nums.length;i+=k){count[nums[i]]++;size++;}int minimum=Arrays.stream(dp).min().getAsInt();int[] next=new int[1024];Arrays.fill(next,minimum+size);for(int state=0;state<1024;state++)for(int value=0;value<1024;value++)if(count[value]>0)next[state^value]=Math.min(next[state^value],dp[state]+size-count[value]);dp=next;}return dp[0];} }
